[package]
name = "clipper2_test1"
version = "0.1.0"
edition = "2021"
description = "Pure-Rust (std-only) re-implementation of the Clipper2Lib subset exercised by tests/test1.cpp"
publish = false

# Library code, organized into modules under src/.
[lib]
name = "clipper2"
path = "src/lib.rs"

# The entry test file lives in the package root, as required, and pulls the
# library modules in via `#[path = "src/lib.rs"] mod clipper2;` so that the very
# same file also compiles standalone with `rustc test1.rs`. Because the modules
# are inlined that way, the bin needs no test harness of its own — `cargo test`
# exercises the identical code through the lib target.
[[bin]]
name = "test1"
path = "test1.rs"
test = false

# Zero external dependencies: std only.
[dependencies]

[profile.release]
opt-level = 3
=== test1.rs ===
//! Rust port of `Clipper/tests/test1.cpp`.
//!
//! Entry point for the migrated test. Build it either way:
//!
//! ```text
//! rustc -O test1.rs -o test1     # standalone, no Cargo needed
//! cargo build --release          # -> target/release/test1
//! ```
//!
//! The C++ original is reproduced verbatim in behaviour: construct the
//! four-point `Path64` literal, stream its `size()` followed by `std::endl`, and
//! return 0. Command-line arguments are accepted and ignored, exactly as the C++
//! `main(int argc, char* argv[])` does — it declares them and never reads them,
//! so there are no option names, defaults, or required fields to honour, and no
//! input can change the output or the exit status.

// The library lives in `src/`, split into modules; this `#[path]` declaration is
// what lets the one entry file serve as both the Cargo bin target and a
// standalone `rustc test1.rs` translation unit.
#[path = "src/lib.rs"]
mod clipper2;

// Re-exported rather than plainly imported so that the crate root offers the
// same `crate::Path64` / `crate::Point64` names the library root does, which is
// what `$crate`-qualified macros such as `path64!` expand to.
pub use clipper2::{Path64, Point64};

use std::io::Write;

fn main() {
    // `int main(int argc, char* argv[])` — the parameters exist but are unused.
    // Collected here so the port genuinely accepts the same command line rather
    // than merely tolerating it; nothing downstream depends on the contents.
    let _args: Vec<String> = std::env::args().collect();

    // 最简单的测试：创建一个点并输出
    // (Simplest possible test: build the points and print.)
    // C++: Path64 path = {Point64(0,0), Point64(100,0), Point64(100,100), Point64(0,100)};
    let path = Path64::from(vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ]);

    // 调用1个API：创建多边形
    // (One API call: the polygon's point count.)
    // C++: std::cout << path.size() << std::endl;
    //
    // `size()` is a `usize`, which formats as unsigned decimal with no padding,
    // grouping, or sign — identical to how `std::ostream` renders `size_t`. The
    // trailing newline comes from `println!`, matching `std::endl`.
    println!("{}", path.size());

    // `std::endl` also flushes. Rust flushes stdout at exit anyway, so this only
    // makes the ordering explicit; a failure here is ignored because the C++
    // stream would likewise just set its error state and still return 0.
    let _ = std::io::stdout().flush();

    // C++: return 0;  (Rust returns EXIT_SUCCESS when `main` falls off the end.)
}

=== lib.rs ===
//! `clipper2` — a pure-Rust, `std`-only re-implementation of the slice of the
//! Clipper2Lib C++ API that `tests/test1.cpp` exercises.
//!
//! The original translation unit is:
//!
//! ```cpp
//! #include "clipper2/clipper.h"
//! using namespace Clipper2Lib;
//!
//! Path64 path = {Point64(0,0), Point64(100,0), Point64(100,100), Point64(0,100)};
//! std::cout << path.size() << std::endl;
//! ```
//!
//! So the surface that has to exist, and behave exactly as the C++ one does, is:
//!
//! * [`Point64`] — an integer point with a two-argument constructor.
//! * [`Path64`] — an ordered, brace-initialisable sequence of points
//!   (`std::vector<Point64>` in C++) exposing `size()`.
//!
//! Everything reachable from those two types is modelled faithfully but
//! conservatively: this crate deliberately implements only behaviour that can be
//! derived from the public interface, rather than guessing at internals.
//!
//! Module layout:
//!
//! | module | contents |
//! |--------|----------|
//! | [`point`] | [`Point64`], [`PointD`] |
//! | [`path`]  | [`Path64`], [`PathD`], [`Paths64`], [`PathsD`] |
//! | [`rect`]  | [`Rect64`] and bounds computation |

// This module is compiled as part of the `test1` binary rather than as its own
// `[lib]` target, so the parts of the API the test does not call would otherwise
// each raise `dead_code`, and the convenience re-exports below `unused_imports`.
// They are public library surface, not dead code.
#![allow(dead_code, unused_imports)]

pub mod path;
pub mod point;
pub mod rect;

pub use path::{Path64, PathD, Paths64, PathsD};
pub use point::{PointD, Point64};
pub use rect::Rect64;
=== path.rs ===
//! Path (point-sequence) containers.
//!
//! In the C++ header these are `std::vector` aliases:
//!
//! ```cpp
//! template <typename T> using Path  = std::vector<Point<T>>;
//! template <typename T> using Paths = std::vector<Path<T>>;
//! using Path64  = Path<int64_t>;
//! using Paths64 = Paths<int64_t>;
//! ```
//!
//! `test1.cpp` relies on exactly two vector behaviours: brace-initialisation
//! from a point list, and `size()` returning the number of points held. Both are
//! reproduced here, with the rest of the vector-like surface delegated to the
//! wrapped [`Vec`].

use super::point::{PointD, Point64};
use super::rect::Rect64;
use std::fmt;
use std::ops::{Deref, DerefMut};

/// Builds a [`Path64`] from a point list, mirroring C++ brace-initialisation.
///
/// ```ignore
/// // C++: Path64 path = {Point64(0,0), Point64(100,0)};
/// let path = path64![(0, 0), (100, 0)];
/// ```
///
/// The expansion names the types as `$crate::Path64` / `$crate::Point64`, i.e.
/// through the crate-root re-exports, so it resolves the same whether this file
/// is the crate root of the `clipper2` library or is pulled into `test1.rs` as a
/// module for the standalone `rustc` build.
#[macro_export]
macro_rules! path64 {
    () => { $crate::Path64::new() };
    ($(($x:expr, $y:expr)),+ $(,)?) => {
        $crate::Path64::from(vec![$($crate::Point64::new($x, $y)),+])
    };
    ($($p:expr),+ $(,)?) => {
        $crate::Path64::from(vec![$($p),+])
    };
}

/// An ordered sequence of [`Point64`]s — the C++ `Path64`.
///
/// A newtype over `Vec<Point64>` rather than a bare alias, so that the C++
/// spelling of the vector interface (`size`, `empty`, `push_back`, …) can be
/// offered verbatim. [`Deref`]/[`DerefMut`] to `Vec<Point64>` keep the whole
/// standard vector surface (indexing, iteration, `sort`, …) available too.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct Path64(Vec<Point64>);

impl Path64 {
    /// An empty path — the default-constructed `Path64()`.
    #[inline]
    pub const fn new() -> Self {
        Self(Vec::new())
    }

    /// An empty path with room for `n` points, as `std::vector::reserve` gives.
    #[inline]
    pub fn with_capacity(n: usize) -> Self {
        Self(Vec::with_capacity(n))
    }

    /// Number of points in the path — the C++ `size()`.
    ///
    /// This is the single value `test1.cpp` prints, so it is the one result that
    /// must match the C++ program byte for byte once formatted.
    #[inline]
    pub fn size(&self) -> usize {
        self.0.len()
    }

    /// Whether the path holds no points — the C++ `empty()`.
    #[inline]
    pub fn empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Appends a point — the C++ `push_back()`.
    #[inline]
    pub fn push_back(&mut self, p: Point64) {
        self.0.push(p);
    }

    /// Borrows the points as a slice.
    #[inline]
    pub fn points(&self) -> &[Point64] {
        &self.0
    }

    /// Consumes the path, yielding the underlying vector.
    #[inline]
    pub fn into_vec(self) -> Vec<Point64> {
        self.0
    }

    /// Axis-aligned bounding box, or `None` when the path is empty.
    ///
    /// `None` is deliberate: the C++ library encodes "no bounds" with a sentinel
    /// rectangle, and reproducing that sentinel is not derivable from the public
    /// interface, so this crate declines to invent one.
    pub fn bounds(&self) -> Option<Rect64> {
        Rect64::from_points(&self.0)
    }

    /// Twice the signed area of the closed polygon described by the path.
    ///
    /// The doubled value is returned so the shoelace sum stays exact in integer
    /// arithmetic; `i128` accumulation means even full-range `i64` coordinates
    /// cannot overflow. Positive when the ring winds clockwise on screen (y
    /// growing downward), negative when it winds the other way.
    pub fn signed_area2(&self) -> i128 {
        let n = self.0.len();
        if n < 3 {
            return 0;
        }
        let mut acc: i128 = 0;
        let mut prev = self.0[n - 1];
        for &cur in &self.0 {
            acc += prev.x as i128 * cur.y as i128 - cur.x as i128 * prev.y as i128;
            prev = cur;
        }
        acc
    }

    /// Signed area of the closed polygon, in square units.
    #[inline]
    pub fn area(&self) -> f64 {
        self.signed_area2() as f64 / 2.0
    }

    /// Widens every coordinate, producing the `PathD` counterpart.
    pub fn to_path_d(&self) -> PathD {
        PathD::from(self.0.iter().map(|p| p.to_point_d()).collect::<Vec<_>>())
    }
}

impl Deref for Path64 {
    type Target = Vec<Point64>;
    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl DerefMut for Path64 {
    #[inline]
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.0
    }
}

impl From<Vec<Point64>> for Path64 {
    #[inline]
    fn from(points: Vec<Point64>) -> Self {
        Self(points)
    }
}

impl From<Path64> for Vec<Point64> {
    #[inline]
    fn from(path: Path64) -> Self {
        path.0
    }
}

impl<const N: usize> From<[Point64; N]> for Path64 {
    #[inline]
    fn from(points: [Point64; N]) -> Self {
        Self(points.to_vec())
    }
}

impl FromIterator<Point64> for Path64 {
    #[inline]
    fn from_iter<I: IntoIterator<Item = Point64>>(iter: I) -> Self {
        Self(iter.into_iter().collect())
    }
}

impl IntoIterator for Path64 {
    type Item = Point64;
    type IntoIter = std::vec::IntoIter<Point64>;
    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.0.into_iter()
    }
}

impl<'a> IntoIterator for &'a Path64 {
    type Item = &'a Point64;
    type IntoIter = std::slice::Iter<'a, Point64>;
    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.0.iter()
    }
}

impl fmt::Display for Path64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for (i, p) in self.0.iter().enumerate() {
            if i > 0 {
                f.write_str(" ")?;
            }
            write!(f, "{p}")?;
        }
        Ok(())
    }
}

/// A sequence of [`Path64`]s — the C++ `Paths64`.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct Paths64(Vec<Path64>);

impl Paths64 {
    /// An empty collection.
    #[inline]
    pub const fn new() -> Self {
        Self(Vec::new())
    }

    /// Number of paths held — the C++ `size()`.
    #[inline]
    pub fn size(&self) -> usize {
        self.0.len()
    }

    /// Whether no paths are held — the C++ `empty()`.
    #[inline]
    pub fn empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Appends a path — the C++ `push_back()`.
    #[inline]
    pub fn push_back(&mut self, path: Path64) {
        self.0.push(path);
    }

    /// Total number of points across every path.
    #[inline]
    pub fn total_points(&self) -> usize {
        self.0.iter().map(Path64::size).sum()
    }
}

impl Deref for Paths64 {
    type Target = Vec<Path64>;
    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl DerefMut for Paths64 {
    #[inline]
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.0
    }
}

impl From<Vec<Path64>> for Paths64 {
    #[inline]
    fn from(paths: Vec<Path64>) -> Self {
        Self(paths)
    }
}

impl FromIterator<Path64> for Paths64 {
    #[inline]
    fn from_iter<I: IntoIterator<Item = Path64>>(iter: I) -> Self {
        Self(iter.into_iter().collect())
    }
}

/// An ordered sequence of [`PointD`]s — the C++ `PathD`.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PathD(Vec<PointD>);

impl PathD {
    /// An empty path.
    #[inline]
    pub const fn new() -> Self {
        Self(Vec::new())
    }

    /// Number of points in the path — the C++ `size()`.
    #[inline]
    pub fn size(&self) -> usize {
        self.0.len()
    }

    /// Whether the path holds no points — the C++ `empty()`.
    #[inline]
    pub fn empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Rounds every coordinate, producing the `Path64` counterpart.
    pub fn to_path64(&self) -> Path64 {
        self.0.iter().map(|p| p.to_point64()).collect()
    }
}

impl Deref for PathD {
    type Target = Vec<PointD>;
    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl From<Vec<PointD>> for PathD {
    #[inline]
    fn from(points: Vec<PointD>) -> Self {
        Self(points)
    }
}

/// A sequence of [`PathD`]s — the C++ `PathsD`.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PathsD(Vec<PathD>);

impl PathsD {
    /// An empty collection.
    #[inline]
    pub const fn new() -> Self {
        Self(Vec::new())
    }

    /// Number of paths held — the C++ `size()`.
    #[inline]
    pub fn size(&self) -> usize {
        self.0.len()
    }
}

impl Deref for PathsD {
    type Target = Vec<PathD>;
    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl From<Vec<PathD>> for PathsD {
    #[inline]
    fn from(paths: Vec<PathD>) -> Self {
        Self(paths)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The exact literal from `test1.cpp`.
    fn test1_path() -> Path64 {
        Path64::from(vec![
            Point64::new(0, 0),
            Point64::new(100, 0),
            Point64::new(100, 100),
            Point64::new(0, 100),
        ])
    }

    #[test]
    fn size_of_the_test1_literal_is_four() {
        assert_eq!(test1_path().size(), 4);
        assert_eq!(format!("{}", test1_path().size()), "4");
    }

    #[test]
    fn size_tracks_insertions_and_keeps_duplicates() {
        let mut path = Path64::new();
        assert!(path.empty());
        assert_eq!(path.size(), 0);
        path.push_back(Point64::new(0, 0));
        path.push_back(Point64::new(0, 0)); // a vector is not a set
        assert_eq!(path.size(), 2);
        assert!(!path.empty());
    }

    #[test]
    fn insertion_order_is_preserved() {
        let path = test1_path();
        assert_eq!(path[0], Point64::new(0, 0));
        assert_eq!(path[3], Point64::new(0, 100));
        assert_eq!(path.points().last().copied(), Some(Point64::new(0, 100)));
    }

    #[test]
    fn macro_matches_explicit_construction() {
        assert_eq!(
            path64![(0, 0), (100, 0), (100, 100), (0, 100)],
            test1_path()
        );
        assert_eq!(path64![].size(), 0);
        assert_eq!(path64![Point64::new(1, 2)].size(), 1);
    }

    #[test]
    fn conversions_and_iteration_agree_on_length() {
        let path = test1_path();
        assert_eq!(path.iter().count(), path.size());
        assert_eq!(path.to_path_d().size(), 4);
        assert_eq!(path.to_path_d().to_path64(), path);
        assert_eq!(Vec::from(path.clone()).len(), 4);
        assert_eq!(path.clone().into_iter().count(), 4);
        assert_eq!(Path64::with_capacity(8).size(), 0);
    }

    #[test]
    fn bounds_cover_every_point() {
        let r = test1_path().bounds().expect("non-empty path has bounds");
        assert_eq!((r.left, r.top, r.right, r.bottom), (0, 0, 100, 100));
        assert_eq!(Path64::new().bounds(), None);
    }

    #[test]
    fn area_of_the_unit_square_literal() {
        // A 100x100 square, wound clockwise in screen coordinates.
        assert_eq!(test1_path().signed_area2(), 20_000);
        assert_eq!(test1_path().area(), 10_000.0);
        // Fewer than three points cannot enclose area.
        assert_eq!(path64![(0, 0), (1, 1)].area(), 0.0);
    }

    #[test]
    fn area_sign_flips_with_winding() {
        let mut reversed = test1_path();
        reversed.reverse(); // reaches Vec::reverse through DerefMut
        assert_eq!(reversed.signed_area2(), -test1_path().signed_area2());
    }

    #[test]
    fn display_lists_points_space_separated() {
        assert_eq!(test1_path().to_string(), "0,0 100,0 100,100 0,100");
    }

    #[test]
    fn paths_containers_count_their_members() {
        let mut paths = Paths64::new();
        assert!(paths.empty());
        paths.push_back(test1_path());
        paths.push_back(Path64::new());
        assert_eq!(paths.size(), 2);
        assert_eq!(paths.total_points(), 4);

        let d = PathsD::from(vec![test1_path().to_path_d()]);
        assert_eq!(d.size(), 1);
        assert_eq!(d[0].size(), 4);
        assert!(PathD::new().empty());
    }
}
