//! Point types.
//!
//! Mirrors `Clipper2Lib::Point<T>`, of which `Point64` (64-bit integer
//! coordinates) is the instantiation used by `test1.cpp`. `PointD` (double
//! coordinates) is provided alongside it because the C++ header exposes the two
//! as a pair and callers routinely convert between them.

use std::fmt;
use std::ops::{Add, Neg, Sub};

/// A point with 64-bit signed integer coordinates.
///
/// The C++ counterpart is `Clipper2Lib::Point64`, a plain aggregate of two
/// `int64_t` fields, constructed as `Point64(x, y)`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    /// The origin, `(0, 0)` — equivalent to the default-constructed `Point64()`.
    pub const ORIGIN: Self = Self { x: 0, y: 0 };

    /// Constructs a point, matching the C++ `Point64(x, y)` constructor.
    #[inline]
    pub const fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }

    /// Rounds a floating-point pair to the nearest integer point.
    ///
    /// C++ builds `Point64` from `double`s via `std::llround`, which rounds half
    /// away from zero — the same rule as Rust's [`f64::round`].
    #[inline]
    pub fn from_rounded(x: f64, y: f64) -> Self {
        Self::new(x.round() as i64, y.round() as i64)
    }

    /// Translates the point by `(dx, dy)`.
    #[inline]
    pub fn translate(self, dx: i64, dy: i64) -> Self {
        Self::new(self.x + dx, self.y + dy)
    }

    /// Widens the point to floating-point coordinates.
    #[inline]
    pub fn to_point_d(self) -> PointD {
        PointD::new(self.x as f64, self.y as f64)
    }
}

impl From<(i64, i64)> for Point64 {
    #[inline]
    fn from((x, y): (i64, i64)) -> Self {
        Self::new(x, y)
    }
}

impl From<Point64> for (i64, i64) {
    #[inline]
    fn from(p: Point64) -> Self {
        (p.x, p.y)
    }
}

impl Add for Point64 {
    type Output = Self;
    #[inline]
    fn add(self, rhs: Self) -> Self {
        Self::new(self.x + rhs.x, self.y + rhs.y)
    }
}

impl Sub for Point64 {
    type Output = Self;
    #[inline]
    fn sub(self, rhs: Self) -> Self {
        Self::new(self.x - rhs.x, self.y - rhs.y)
    }
}

impl Neg for Point64 {
    type Output = Self;
    #[inline]
    fn neg(self) -> Self {
        Self::new(-self.x, -self.y)
    }
}

/// Renders the point as `x,y`.
///
/// Note: this is this crate's own convention for diagnostics. `test1.cpp` never
/// streams a `Point64`, so no claim is made here about byte-compatibility with
/// the C++ `operator<<`; only [`Path64::size`](crate::path::Path64::size) output
/// is contractually reproduced.
impl fmt::Display for Point64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{}", self.x, self.y)
    }
}

/// A point with `f64` coordinates — the C++ `Clipper2Lib::PointD`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    /// Constructs a point, matching the C++ `PointD(x, y)` constructor.
    #[inline]
    pub const fn new(x: f64, y: f64) -> Self {
        Self { x, y }
    }

    /// Rounds to the nearest [`Point64`], half away from zero.
    #[inline]
    pub fn to_point64(self) -> Point64 {
        Point64::from_rounded(self.x, self.y)
    }
}

impl From<(f64, f64)> for PointD {
    #[inline]
    fn from((x, y): (f64, f64)) -> Self {
        Self::new(x, y)
    }
}

impl From<Point64> for PointD {
    #[inline]
    fn from(p: Point64) -> Self {
        p.to_point_d()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_stores_coordinates_verbatim() {
        let p = Point64::new(100, -100);
        assert_eq!((p.x, p.y), (100, -100));
        assert_eq!(Point64::default(), Point64::ORIGIN);
    }

    #[test]
    fn equality_is_componentwise() {
        assert_eq!(Point64::new(0, 0), Point64::from((0, 0)));
        assert_ne!(Point64::new(0, 1), Point64::new(1, 0));
    }

    #[test]
    fn arithmetic_matches_cpp_operators() {
        let a = Point64::new(3, 4);
        let b = Point64::new(10, 20);
        assert_eq!(a + b, Point64::new(13, 24));
        assert_eq!(b - a, Point64::new(7, 16));
        assert_eq!(-a, Point64::new(-3, -4));
        assert_eq!(a.translate(-3, -4), Point64::ORIGIN);
    }

    #[test]
    fn rounding_is_half_away_from_zero() {
        assert_eq!(Point64::from_rounded(0.5, -0.5), Point64::new(1, -1));
        assert_eq!(Point64::from_rounded(1.4, -1.6), Point64::new(1, -2));
        assert_eq!(PointD::new(2.5, 3.5).to_point64(), Point64::new(3, 4));
    }

    #[test]
    fn conversions_round_trip() {
        let p = Point64::new(100, 100);
